class Solution {
public:
    int minSubArrayLen(int target, vector<int>& nums) {
        int n = nums.size();
        int left = 0;
        long long curSum = 0;
        int ans = n + 1;               // sentinel larger than any possible length
        for (int right = 0; right < n; ++right) {
            curSum += nums[right];
            while (curSum >= target) {
                ans = min(ans, right - left + 1);
                curSum -= nums[left];
                ++left;
            }
        }
        return (ans == n + 1) ? 0 : ans;
    }
};

